package solution

import (
	"errors"
	"sort"
	"strconv"
)

var (
	ErrInvalidAsset  = errors.New("invalid asset")
	ErrAssetExists   = errors.New("asset already exists")
	ErrAssetNotFound = errors.New("asset not found")
)

type Asset struct {
	ID, Name, Zone string
	Tags           []string
}

type Inventory struct {
	items map[string]Asset
}

func NewInventory() *Inventory {
	return &Inventory{items: make(map[string]Asset)}
}

func validAsset(a Asset) bool {
	n, err := strconv.Atoi(a.ID)
	if err != nil || n <= 0 || strconv.Itoa(n) != a.ID || a.Name == "" || a.Zone == "" {
		return false
	}
	for _, tag := range a.Tags {
		if tag == "" {
			return false
		}
	}
	return true
}

func copyAsset(a Asset) Asset {
	a.Tags = append([]string(nil), a.Tags...)
	return a
}

func (i *Inventory) Add(a Asset) error {
	if !validAsset(a) {
		return ErrInvalidAsset
	}
	if _, ok := i.items[a.ID]; ok {
		return ErrAssetExists
	}
	i.items[a.ID] = copyAsset(a)
	return nil
}

func (i *Inventory) Update(a Asset) error {
	if !validAsset(a) {
		return ErrInvalidAsset
	}
	if _, ok := i.items[a.ID]; !ok {
		return ErrAssetNotFound
	}
	i.items[a.ID] = copyAsset(a)
	return nil
}

func (i *Inventory) Delete(id string) error {
	if _, ok := i.items[id]; !ok {
		return ErrAssetNotFound
	}
	delete(i.items, id)
	return nil
}

func (i *Inventory) Get(id string) (Asset, error) {
	a, ok := i.items[id]
	if !ok {
		return Asset{}, ErrAssetNotFound
	}
	return copyAsset(a), nil
}

func (i *Inventory) IDs() []string {
	out := make([]string, 0, len(i.items))
	for id := range i.items {
		out = append(out, id)
	}
	sort.Strings(out)
	return out
}

func (i *Inventory) Snapshot() map[string]Asset {
	out := make(map[string]Asset, len(i.items))
	for id, a := range i.items {
		out[id] = copyAsset(a)
	}
	return out
}

func (i *Inventory) Clear() { i.items = make(map[string]Asset) }
